  await symlink(join(repo, 'node_modules'), join(work, 'node_modules'), 'dir');
  // The repository's node_modules/ pattern ignores directories, not symlinks.
  // Keep this dry-run convenience local to the disposable clone's Git excludes.
  await appendFile(join(work, '.git/info/exclude'), '\n/node_modules\n');
}

export async function runDaily({ repo = ROOT, home = '/opt/benchmarkheaven-daily', runDir, dryRun = false } = {}) {
  repo = resolve(repo); home = resolve(home);
  const started = new Date().toISOString(), day = started.slice(0, 10);
  runDir = resolve(runDir || join(home, 'runs', `${started.replace(/[:.]/g, '-')}-${process.pid}`));
  const work = join(runDir, 'work'), reports = join(runDir, 'reports');
  await mkdir(reports, { recursive: true });
  await mkdir(join(runDir, 'sources'), { recursive: true });
  await mkdir(home, { recursive: true });
  const report = { started_at: started, run_dir: runDir, dry_run: dryRun, steps: [], published: false, exit_code: 1 };
  let before, after, top5 = null;
  const environment = { ...process.env, BH_EVIDENCE_DIR: join(runDir, 'sources'), BH_STATE: join(runDir, 'workers'), BH_WORKER_MAX_PRICE_PER_1M: '4', BH_WORKER_REASONING_EFFORT: 'low', BH_WORKER_DISABLE_OPTIONAL_REASONING: '0' };
  for (const key of ['OPENAI_API_KEY', 'OPENAI_BASE_URL', 'OPENAI_API_BASE', 'CODEX_API_KEY']) delete environment[key];
  const command = async (name, file, args, cwd = work, timeout = 600_000) => {
    const begin = Date.now();
    try {
      const { stdout, stderr } = await exec(file, args, { cwd, env: environment, timeout, killSignal: 'SIGTERM', maxBuffer: 32_000_000 });
      await writeFile(join(reports, `${name.replace(/[^a-z0-9-]/gi, '-')}.log`), redact(stdout + stderr));
      report.steps.push({ name, ok: true, duration_ms: Date.now() - begin });
      console.log(`OK ${name}`);
      return stdout.trimEnd();
    } catch (error) {
      const detail = redact([error.stdout, error.stderr, error.message].filter(Boolean).join('\n'));
      await writeFile(join(reports, `${name.replace(/[^a-z0-9-]/gi, '-')}.log`), detail);
      report.steps.push({ name, ok: false, duration_ms: Date.now() - begin, error: detail.slice(-3000) });
      throw new Error(`${name} FAILED: ${detail.slice(-1800)}`);
    }
  };
  const git = (name, args, cwd = repo) => command(name, 'git', args, cwd, 120_000);
  const status = async (name, cwd) => parseStatusPorcelain(await git(name, ['status', '--porcelain=v1', '--untracked-files=all'], cwd));
  console.log(`Benchmark Heaven daily ${started}: ${runDir}${dryRun ? ' (dry run)' : ''}`);
  try {
    if (await git('branch', ['branch', '--show-current']) !== 'main') throw new Error('Daily publication requires the main checkout');
    const dirty = await status('initial-status', repo);
    if (!dryRun && dirty.length) throw new Error('Daily publication requires a clean checkout; owner changes were preserved');
    await git('fetch-main', ['fetch', 'origin', 'main']);
    if (!dryRun) await git('sync-main', ['merge', '--ff-only', 'origin/main']);
    const base = await git('base', ['rev-parse', 'HEAD']);
    const remote = await git('remote-base', ['rev-parse', 'origin/main']);
    if (!dryRun && base !== remote) throw new Error('Local main has unpublished commits; refusing to include them in a daily push');
    report.base = base;
    before = await readJSON(join(repo, 'data/dataset.json'));
    await writeJSONAtomic(join(reports, 'dataset-before.json'), before);
    await command('clone', 'git', ['clone', '--no-hardlinks', repo, work], repo, 120_000);
    await git('detach-stage', ['checkout', '--detach', base], work);
    const overlayHashes = new Map();
    if (dryRun) {
      for (const entry of dirty) {
        const target = resolve(work, entry.path);
        if (!target.startsWith(work + sep)) throw new Error('Unsafe dry-run overlay path');
        if (entry.code.includes('D')) { await rm(target, { recursive: true, force: true }); overlayHashes.set(entry.path, null); continue; }
        await mkdir(dirname(target), { recursive: true });
        await cp(join(repo, entry.path), target, { recursive: true });
        if ((await stat(target)).isFile()) overlayHashes.set(entry.path, hash(await readFile(target)));
      }
      await linkDryRunDependencies(repo, work);
    } else await command('npm-ci', 'npm', ['ci', '--no-audit', '--no-fund'], work, 900_000);
    await cp(join(work, 'data/raw'), join(runDir, 'before/raw'), { recursive: true });
    const legacy = hash(await readFile(join(work, 'data/raw/aa-coding-agents.json')));
    const catalog = JSON.parse(await command('worker-catalog', process.execPath, ['ops/rebuild-2026-09/bin/pick-worker-models.mjs', '--json']));
    report.workers = selectProducerCritic(catalog);
    await writeJSONAtomic(join(reports, 'worker-catalog.json'), catalog);
    await writeJSONAtomic(join(reports, 'workers.json'), report.workers);
    for (const source of ['aa', 'da', 'or']) await command(`fetch-${source}`, process.execPath, ['scripts/fetch-live.mjs', source], work, 1_800_000);
    await command('fetch-coding-v1.5', process.execPath, ['scripts/fetch-aa-coding-agents.mjs']);
    await command('review-live', process.execPath, ['ops/daily/phase-step.mjs', 'live', runDir], work, 3_600_000);
    await command('refresh-benchmarks', process.execPath, ['ops/daily/phase-step.mjs', 'benchmarks', runDir], work, 3_600_000);
    if (hash(await readFile(join(work, 'data/raw/aa-coding-agents.json'))) !== legacy) throw new Error('Legacy Coding Agent v1.4 changed: refusing publication');
    await command('build-dataset', process.execPath, ['scripts/build-dataset.mjs']);
    await command('npm-build', 'npm', ['run', 'build'], work, 1_200_000);
    await command('npm-test', 'npm', ['test'], work, 900_000);
    await command('typecheck', 'npx', ['tsc', '--noEmit', '-p', '.']);
    await command('prerender', process.execPath, ['--test', 'test/production/prerender.mjs']);
    after = await readJSON(join(work, 'data/dataset.json'));
    for (const key of ['artificialanalysis', 'designarena', 'openrouter', 'aa_coding_agents_v1_5', 'aa_efficiency', 'openrouter_efficiency', 'chutes_efficiency']) {
      if (after.sources[key]?.slice(0, 10) !== day) throw new Error(`Source ${key} is not today's collector run (${after.sources[key]})`);
    }
    top5 = JSON.parse(await command('top5', process.execPath, ['scripts/top5.mjs', '5']));
    await writeJSONAtomic(join(reports, 'dataset-after.json'), after);
    const changed = [];
    for (const entry of await status('stage-status', work)) {
      if (dryRun && overlayHashes.has(entry.path) && !entry.path.startsWith('data/')) {
        const current = await readFile(join(work, entry.path)).then(hash).catch((e) => { if (e.code === 'ENOENT') return null; throw e; });
        if (current === overlayHashes.get(entry.path)) continue;
      }
      changed.push(entry.path);
    }
    const extra = await readJSON(join(reports, 'commit-paths.json')).catch((e) => { if (e.code === 'ENOENT') return {}; throw e; });
    const scope = assessCommitScope(changed, extra.extra_allowed || []);
    if (!scope.ok) throw new Error(`Daily commit scope rejected: ${scope.rejected.join(', ')}`);
    report.changed_paths = scope.allowed;
    if (!dryRun && scope.allowed.length) {
      await git('stage-data', ['add', '--', ...scope.allowed], work);
      const userName = await git('git-name', ['config', 'user.name']);
      const userEmail = await git('git-email', ['config', 'user.email']);
      await git('commit-data', ['-c', `user.name=${userName}`, '-c', `user.email=${userEmail}`, 'commit', '-m', `Refresh Benchmark Heaven data ${day}\n\nSource-backed daily gauntlet and build/tests/typecheck passed.\n\n${COMMIT_TRAILER}`], work);
      const sha = await git('candidate-commit', ['rev-parse', 'HEAD'], work);
      if (await git('recheck-head', ['rev-parse', 'HEAD']) !== base || (await status('recheck-status', repo)).length) throw new Error('Main changed during collection; candidate remains isolated');
      const remoteUrl = await git('remote-url', ['remote', 'get-url', 'origin']);
      // Push from staging first: a rejected push leaves the primary checkout untouched.
      await git('push-data', ['push', remoteUrl, 'HEAD:refs/heads/main'], work);
      report.published = true; report.commit = sha;
      if (await git('post-push-head', ['rev-parse', 'HEAD']) !== base || (await status('post-push-status', repo)).length) throw new Error('Main changed after push; published revision is green, local edits were preserved');
      await git('fetch-published', ['fetch', 'origin', 'main']);
      await git('install-published', ['merge', '--ff-only', sha]);
      const deadline = Date.now() + 600_000;
      let last = '';
      const pending = new Set(['benchmarkheaven.com', 'model-market-comparison.app.mintapis.com']);
      while (pending.size && Date.now() < deadline) {
        for (const host of pending) {
          try {
            const response = await fetch(`https://${host}/api/dataset?t=${Date.now()}`, { signal: AbortSignal.timeout(20_000) });
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const published = await response.json();
            if (matchesPublishedSnapshot(published, after)) pending.delete(host);
            else last = `${host}: snapshot mismatch`;
          } catch (error) { last = error.message; }
        }
        if (pending.size) await new Promise((done) => setTimeout(done, 20_000));
      }
      if (pending.size) throw new Error(`Webhook deploy verification failed (${last}); no duplicate deployment queued`);
      report.live_verified = true;
    }
    report.exit_code = 0;
  } catch (error) { report.error = redact(error.message); console.error(`DAILY FAILED: ${report.error}`); }
  report.finished_at = new Date().toISOString();
  const workerFiles = await readdir(join(runDir, 'workers')).catch((e) => { if (e.code === 'ENOENT') return []; throw e; });
  const calls = [];
  for (const file of workerFiles.filter((f) => /^worker(?:-failure)?-.*\.json$/.test(f))) {
    const receipt = await readJSON(join(runDir, 'workers', file));
    calls.push({ receipt: file, role: receipt.mode, actual_model: receipt.actual_model ?? null,
      requested_model: receipt.requested_model, status: receipt.status ?? 'complete',
      returned_cost_usd: Number.isFinite(receipt.usage?.cost) ? receipt.usage.cost : null, reasoning: receipt.reasoning });
  }
  report.worker_calls = { calls, returned_cost_usd: calls.reduce((sum, r) => sum + (r.returned_cost_usd ?? 0), 0),
    calls_without_returned_cost: calls.filter((r) => r.returned_cost_usd === null).length,
    note: 'Sum of returned charges only, including charged failed completions where reported. Missing charges and owner subscription usage are not estimated.' };
  await writeJSONAtomic(join(reports, 'worker-calls.json'), report.worker_calls);
  if (after) report.dataset_sha256 = hash(await readFile(join(work, 'data/dataset.json')));
  try { report.storage = await compactPublishedRun({ runDir, published: report.published, liveVerified: report.live_verified, dryRun }); }
  catch (error) { report.storage = { applied: false, error: redact(error.message) }; console.error(`DAILY STORAGE CLEANUP FAILED: ${report.storage.error}`); }
  const summary = [
    `STATUS: ${report.exit_code === 0 ? 'ok' : 'problem'}`,
    `Benchmark Heaven ${day}${dryRun ? ' — vollstaendiger Testlauf ohne Push/Telegram' : ''}`,
    `Lauf: ${runDir}`,
    report.workers ? `Erste Auswahl: ${report.workers.producer.id}; Kritiker: ${report.workers.critic.id}` : 'Worker-Auswahl nicht abgeschlossen.',
    `Modelle mit Abschluss: ${[...new Set(calls.filter((r) => r.status === 'complete').map((r) => r.actual_model))].filter(Boolean).join(', ') || 'keine'}; gemeldete Kosten: $${report.worker_calls.returned_cost_usd.toFixed(4)} (${report.worker_calls.calls_without_returned_cost} Aufrufe ohne Kostenangabe).`,
    `Schritte: ${report.steps.filter((s) => s.ok).length} erfolgreich; ${report.steps.filter((s) => !s.ok).length} fehlgeschlagen.`,
    `Publikation: ${report.published ? report.commit : dryRun ? 'Testlauf' : 'keine'}; Live-Pruefung: ${report.live_verified ? 'OK' : 'nicht erfolgt'}.`,
    report.error ? `FEHLER: ${report.error.split('\n').filter(Boolean).at(-1).slice(0, 800)}` : 'Build, Tests, Typpruefung und Quellpruefung erfolgreich.',
  ].join('\n') + '\n';
  await writeFile(join(home, 'last-summary.txt'), summary);
  await writeFile(join(reports, 'summary.txt'), summary);
  await writeJSONAtomic(join(reports, 'run-report.json'), report);
  const context = { status_ok: report.exit_code === 0, rc: report.exit_code, top5: top5 ? { current: top5 } : null, datasets: { before: slim(before), after: slim(after) } };
  await writeJSONAtomic(join(reports, 'notify-context.json'), context);
  await executeNotifications({ context, stateDir: join(home, 'state'), dryRun }).catch((e) => console.error(`NOTIFICATION FAILED: ${redact(e.message)}`));
  console.log(summary);
  return report;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  const argv = process.argv.slice(2), option = (key) => { const index = argv.indexOf(key); if (index < 0) return undefined; if (!argv[index + 1] || argv[index + 1].startsWith('--')) throw new Error(`Missing ${key} value`); return argv[index + 1]; };
  runDaily({ repo: option('--repo'), home: option('--home'), runDir: option('--run-dir'), dryRun: argv.includes('--dry-run') })
    .then((result) => { process.exitCode = result.exit_code; }).catch((error) => { console.error(`DAILY FATAL: ${redact(error.message)}`); process.exitCode = 1; });
}

#!/usr/bin/env node
// ops/daily/notify.mjs — quiet-by-default Telegram notifier for the daily run.
//
// Policy lives in ./policy.mjs (pure, tested); this module owns IO: state
// files, the Telegram send, and the dedup rule that a notification key is
// persisted ONLY after a send genuinely succeeded. Missing credentials never
// produce a "sent" record, so a later run with working credentials still
// delivers the event. Sends that FAIL (transport or credentials) are kept as
// pending payloads and retried on a later run; a successful run that advances
// the top5 baseline therefore cannot silently drop an event. Dedup entries and
// the 7-day failure-alert stamp are written only after a CONFIRMED send.
// A successful run also clears any stale escalation request.
//
// State files in <home>/state (kept identical in spirit to the old runtime):
//   top5-state.json       last Composite top-5 rows (array; seeded on first run)
//   failure-alert.stamp   mtime of the last successfully sent failure alert
//   daily-state.json      { notified: {key: iso}, failure_streak, escalation_request, pending, last_run }
//   escalation-request.json  written once when the failure streak crosses 3
//
// CLI (also used by run.sh as a crash fallback):
//   node notify.mjs --home /opt/benchmarkheaven-daily [--run-dir DIR] [--rc N]
//                   [--dry-run] [--fallback]
// --fallback sends only a minimal failure alert and only when daily.mjs did
// not already finish its own notification pass within the last 3 hours.
import { mkdir, readFile, stat, writeFile, rename, rm, utimes, open } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { parseJsonTolerant, planNotifications } from './policy.mjs';

export const DEFAULT_HOME = '/opt/benchmarkheaven-daily';
const FALLBACK_FRESH_MS = 3 * 60 * 60 * 1000;
const TG_TIMEOUT_MS = 30_000;

// --- small atomic JSON helper (state writes must never half-land) ----------
async function writeJsonAtomic(path, value) {
  await mkdir(dirname(path), { recursive: true });
  const tmp = `${path}.${process.pid}.tmp`;
  try {
    await writeFile(tmp, JSON.stringify(value, null, 1) + '\n', { flag: 'wx' });
    await rename(tmp, path);
  } finally { await rm(tmp, { force: true }); }
}

async function readJsonFile(path, fallback = null) {
  try { return parseJsonTolerant(await readFile(path, 'utf8'), fallback); }
  catch (error) { if (error.code === 'ENOENT') return fallback; throw error; }
}

// --- state ------------------------------------------------------------------
export async function readNotifyState(stateDir) {
  const top5Previous = await readJsonFile(join(stateDir, 'top5-state.json'), null);
  const daily = await readJsonFile(join(stateDir, 'daily-state.json'), null) ?? {};
  let failureAlertLastSentAt = null;
  try { failureAlertLastSentAt = (await stat(join(stateDir, 'failure-alert.stamp'))).mtimeMs; }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
  return {
    top5Previous: Array.isArray(top5Previous) ? top5Previous : null,
    notified: daily.notified && typeof daily.notified === 'object' ? daily.notified : {},
    failure_streak: Number.isSafeInteger(daily.failure_streak) ? daily.failure_streak : 0,
    escalation_request: daily.escalation_request ?? null,
    pending: Array.isArray(daily.pending)
      ? daily.pending.filter((p) => p && typeof p.text === 'string')
      : [],
    last_run: daily.last_run ?? null,
    failureAlertLastSentAt,
  };
}

// --- Telegram ----------------------------------------------------------------
// Returns { sent, reason? }; never throws — a transport failure must be loud
// in the log but must not mask the daily run's own exit code. Error text is
// sanitized: it must never contain the bot token (fetch errors can embed the
// full request URL, which includes it).
export async function sendTelegram(text, { token, chatId, fetchImpl = fetch } = {}) {
  if (!token || !chatId) return { sent: false, reason: 'missing_credentials' };
  try {
    const response = await fetchImpl(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text: String(text).slice(0, 4000) }),
      signal: AbortSignal.timeout(TG_TIMEOUT_MS),
    });
    const body = await response.json().catch(() => null);
    if (!response.ok || body?.ok !== true) return { sent: false, reason: `telegram_http_${response.status}` };
    return { sent: true };
  } catch (error) {
    let reason = `transport:${error && error.message ? error.message : 'unknown error'}`;
    if (token) reason = reason.split(token).join('[redacted]');
    return { sent: false, reason };
  }
}

// --- the one entry point ------------------------------------------------------
// context: { status_ok, rc, top5: {previous, current}, datasets: {before, after},
//            summary_excerpt } — exactly what daily.mjs writes into
//            reports/notify-context.json (datasets inlined, not paths).
export async function executeNotifications({
  context, stateDir, dryRun = false,
  env = process.env, fetchImpl = fetch, now = Date.now(),
} = {}) {
  if (!context || typeof context.status_ok !== 'boolean') throw new Error('notify context with boolean status_ok is required');
  const state = await readNotifyState(stateDir);
  const plan = planNotifications({
    status_ok: context.status_ok, rc: context.rc ?? null,
    top5: { previous: context.top5?.previous ?? state.top5Previous, current: context.top5?.current ?? [] },
    datasets: { before: context.datasets?.before ?? null, after: context.datasets?.after ?? null },
    failure_streak: state.failure_streak,
    failure_alert_last_sent_at: state.failureAlertLastSentAt,
    notified: state.notified, escalation_request: state.escalation_request,
    summary_excerpt: context.summary_excerpt ?? null, now,
  });
  // Pending DATA events are replayed first. Failure alerts are replanned from
  // current status through the weekly gate; recovery drops stale unsent failures.
  // Replaying them directly would bypass weekly dedup and report resolved problems.
  const pendingReplay = state.pending.filter((p) => p.kind !== 'failure' && !state.notified[p.key]).map((p) => ({
    kind: p.kind ?? 'pending', key: p.key ?? null, text: p.text, onSent: p.onSent ?? null, pending: true,
  }));
  const pendingKeys = new Set(pendingReplay.map((p) => p.key).filter((k) => typeof k === 'string' && k));
  const sends = [
    ...pendingReplay,
    ...plan.sends.filter((s) => !(typeof s.key === 'string' && pendingKeys.has(s.key))),
  ];
  for (const s of sends) console.log(`notify: plan send ${s.kind} [${s.key}]${s.pending ? ' (retry)' : ''}`);
  for (const s of plan.skips) console.log(`notify: skip ${s.kind}${s.key ? ` [${s.key}]` : ''} (${s.reason})`);
  if (dryRun) { console.log('notify: --dry-run — no sends, no state writes'); return { dryRun: true, plan, sent: [], failed: [] }; }

  const sent = []; const failed = []; const pendingNext = [];
  const notifiedAdditions = {};
  let failureStampMs = null;
  for (const send of sends) {
    const result = await sendTelegram(send.text, { token: env.TG_BOT_TOKEN, chatId: env.TG_CHAT_ID, fetchImpl });
    if (result.sent) {
      console.log(`notify: sent ${send.kind} [${send.key}]`);
      sent.push(send.kind);
      if (send.onSent?.notified_key) notifiedAdditions[send.onSent.notified_key] = plan.evaluated_at;
      if (send.onSent?.failure_alert_sent_at) failureStampMs = now;
    } else {
      console.error(`notify: NOT SENT ${send.kind} [${send.key}]: ${result.reason}`);
      failed.push({ kind: send.kind, key: send.key, reason: result.reason });
      // Keep the exact payload for a later retry; dedup is NOT recorded for it.
      pendingNext.push({ kind: send.kind, key: send.key, text: send.text, onSent: send.onSent ?? null });
    }
  }

  // Escalation request is intentionally NOT gated on a Telegram send: it is a
  // local operator signal (loud log line + state file), never a notification
  // policy bypass. A successful run clears the stale request (state + file).
  if (!context.status_ok && plan.baseline.escalation_request) {
    console.error(`ESCALATION REQUESTED: ${plan.baseline.escalation_request.streak} consecutive failures — run ops/daily/escalate.sh --operator`);
    await writeJsonAtomic(join(stateDir, 'escalation-request.json'), { ...plan.baseline.escalation_request, run_status_rc: context.rc ?? null });
  }
  if (context.status_ok) await rm(join(stateDir, 'escalation-request.json'), { force: true });

  // Baseline seeding and streak bookkeeping persist even when nothing was
  // sent; dedup keys and the failure stamp persist only after a real send.
  // A failed run never advances the top5 baseline (plan keeps `previous`),
  // and a fallback context (no top5 supplied) never erases an existing one.
  if (Array.isArray(plan.baseline.top5_state)) {
    await writeJsonAtomic(join(stateDir, 'top5-state.json'), plan.baseline.top5_state);
  }
  if (failureStampMs !== null) {
    const stamp = join(stateDir, 'failure-alert.stamp');
    await mkdir(stateDir, { recursive: true });
    await (await open(stamp, 'a')).close();
    const when = new Date(failureStampMs);
    await utimes(stamp, when, when);
  }
  await writeJsonAtomic(join(stateDir, 'daily-state.json'), {
    notified: { ...state.notified, ...notifiedAdditions },
    failure_streak: plan.baseline.failure_streak,
    escalation_request: context.status_ok ? null : (plan.baseline.escalation_request ?? state.escalation_request),
    pending: pendingNext,
    last_run: { at: new Date(now).toISOString(), status_ok: context.status_ok, rc: context.rc ?? null, sent, failed: failed.map((f) => f.kind) },
  });
  return { dryRun: false, plan, sent, failed };
}

// --- CLI ----------------------------------------------------------------------
async function main(argv) {
  const option = (name) => { const i = argv.indexOf(name); return i < 0 ? null : argv[i + 1]; };
  const home = option('--home') ?? DEFAULT_HOME;
  const stateDir = option('--state-dir') ?? join(home, 'state');
  const dryRun = argv.includes('--dry-run');
  const rc = option('--rc') !== null ? Number(option('--rc')) : null;
  let context = null;
  const runDir = option('--run-dir');
  if (runDir) {
    context = await readJsonFile(join(runDir, 'reports', 'notify-context.json'), null);
    if (!context) throw new Error(`no notify context under ${runDir}/reports — daily.mjs writes it at the end of every run`);
  }
  if (!context) {
    if (argv.includes('--fallback')) {
      const state = await readNotifyState(stateDir);
      if (state.last_run?.at && (option('--started-at') ? Date.parse(state.last_run.at) >= Date.parse(option('--started-at')) : Date.now() - Date.parse(state.last_run.at) < FALLBACK_FRESH_MS)) {
        console.log('notify --fallback: daily.mjs already handled notifications recently; nothing to do');
        return;
      }
      if (rc === 0) { console.log('notify --fallback: rc=0, nothing to report'); return; }
    }
    if (rc === null) throw new Error('usage: notify.mjs --run-dir DIR | --rc N [--fallback] [--dry-run]');
    context = { status_ok: rc === 0, rc, top5: null, datasets: null, summary_excerpt: null };
  }
  const result = await executeNotifications({ context, stateDir, dryRun });
  if (result.failed?.length) process.exitCode = 2;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  main(process.argv.slice(2)).catch((error) => { console.error(`NOTIFY_ERROR: ${error.message}`); process.exitCode = 1; });
}

// ops/daily/policy.mjs — phase 08 daily orchestration policy.
//
// Pure functions only: no filesystem, no network, no clock (pass `now` in).
// Every decision the daily run or the notifier makes is computed here so that
// test/daily-policy.test.mjs can pin the exact behaviour. Silent weakening is
// treated as a bug: malformed state degrades to "no comparison possible",
// never to "everything is fine".

// --- Tunables (master brief §6 + phase 08 contract) ------------------------
export const TOP_N = 5; // Composite top-N family watchlist
export const NOTABLE_AA_INDEX = 55; // "meaningful new major model": AA index >= 55 ...
export const DIVERGENCE_ALERT_PP = 10; // ... or new exact divergence >= 10 percentage points
export const FAILURE_ALERT_INTERVAL_MS = 7 * 24 * 60 * 60 * 1000; // failure alert at most once / 7d
export const ESCALATION_THRESHOLD = 3; // consecutive failures before an escalation request
export const MAX_WORKER_USD_PER_MTOK = 4; // daily workers: <= $4 per million prompt AND completion
export const MIN_WORKER_AA_INDEX = 34; // hard gate, same as worker-policy.mjs
export const COMMIT_TRAILER = 'Co-Authored-By: Codex GPT-6 Astra (Sandy rebuild) <noreply@openai.com>';
// A daily commit may contain data, and only explicitly declared new source
// evidence (refreshBenchmarks reports those paths). Nothing else. Ever.
export const ALLOWED_COMMIT_PREFIXES = ['data/'];

// --- Tolerant parsing ------------------------------------------------------
// Malformed or partial snapshots must never crash the notifier and must never
// be interpreted as a clean baseline.
export function parseJsonTolerant(text, fallback = null) {
  if (typeof text !== 'string' || !text.trim()) return fallback;
  try { return JSON.parse(text); } catch { return fallback; }
}

// A usable top-N row is exactly {family_key: string, name: string, composite: finite number}.
// Partial rows are dropped; a non-array yields null ("unknown", distinct from "empty").
export function sanitizeTop5(value) {
  if (value === null || value === undefined) return null;
  if (!Array.isArray(value)) return null;
  return value.filter((row) => row && typeof row.family_key === 'string' && row.family_key.trim()
    && typeof row.name === 'string' && Number.isFinite(row.composite));
}

// previous === null or malformed  => no usable baseline: seed, notify nobody.
// An empty-but-valid baseline ("known empty") is also seeded rather than
// spamming five "new" entrants after a state-file loss.
// Returns { seeded, entrants } where entrants are full current rows in rank order.
export function diffTop5Entrants(previous, current) {
  const curr = sanitizeTop5(current) ?? [];
  const before = sanitizeTop5(previous);
  if (before === null || before.length === 0) return { seeded: true, entrants: [] };
  const known = new Set(before.map((row) => row.family_key));
  return { seeded: false, entrants: curr.filter((row) => !known.has(row.family_key)) };
}

// --- New major models ------------------------------------------------------
// "Meaningful new major model": AA intelligence index >= NOTABLE_AA_INDEX on a
// model whose family was entirely absent from the previous dataset.
// Several reasoning variants of one new family collapse into a single event,
// represented by the variant with the highest AA index.
function aaIndexValue(model) {
  const value = model?.benchmarks?.aa_intelligence_index;
  return Number.isFinite(value) ? value : null;
}

export function findNewMajorModels(before, after, { minIndex = NOTABLE_AA_INDEX } = {}) {
  const beforeModels = Array.isArray(before?.models) ? before.models : [];
  const afterModels = Array.isArray(after?.models) ? after.models : [];
  const known = new Set(beforeModels.map((m) => m?.family_key).filter((f) => typeof f === 'string' && f));
  const bestPerFamily = new Map();
  for (const m of afterModels) {
    const index = aaIndexValue(m);
    if (index === null || index < minIndex) continue;
    const family = typeof m?.family_key === 'string' && m.family_key ? m.family_key : null;
    if (!family || known.has(family)) continue;
    const candidate = { id: m.id ?? null, family_key: family, name: m.family_name || m.display_name || m.id || family, index };
    const best = bestPerFamily.get(family);
    if (!best || candidate.index > best.index
      || (candidate.index === best.index && String(candidate.id).localeCompare(String(best.id)) < 0)) {
      bestPerFamily.set(family, candidate);
    }
  }
  return [...bestPerFamily.values()].sort((a, b) => b.index - a.index || String(a.id).localeCompare(String(b.id)));
}

// --- Exact-comparable divergences (unit-aware) -----------------------------
// dataset.benchmark_results.divergences rows (lib/benchmark-scores.mjs) carry an
// exact-pair identity: same model, benchmark version, unit, variant, harness and
// reviewed comparison_key. We alert only on *newly appearing* pairs whose absolute
// delta is >= threshold percentage points. Units are never invented and never
// rescaled by an arbitrary constant: a 'percent' delta IS percentage points,
// a 'fraction' delta is converted (x100) into percentage points; every other
// unit (including unscaled 'points', which is not a percentage-point scale)
// is ignored.
function rawDelta(d) {
  if (Number.isFinite(d.delta)) return d.delta;
  const a = d.self_reported_value ?? d.self_reported;
  const b = d.measured_value ?? d.measured;
  return Number.isFinite(a) && Number.isFinite(b) ? a - b : null;
}

export function findNotableDivergences(beforeResults, afterResults, { thresholdPp = DIVERGENCE_ALERT_PP } = {}) {
  const known = new Set((beforeResults?.divergences ?? []).map((d) => d?.id).filter(Boolean));
  const out = [];
  for (const d of afterResults?.divergences ?? []) {
    if (!d?.id || known.has(d.id)) continue;
    const raw = rawDelta(d);
    let deltaPp = null;
    if (d.unit === 'percent') deltaPp = raw;
    else if (d.unit === 'fraction') deltaPp = raw === null ? null : raw * 100;
    // 'points' and any other unit: inherently arbitrary, never percentage points.
    if (deltaPp === null || Math.abs(deltaPp) < thresholdPp) continue;
    out.push({ id: d.id, model_id: d.model_id ?? null, benchmark_id: d.benchmark_id ?? null, unit: d.unit,
      delta: Number.isFinite(d.delta) ? d.delta : raw, delta_pp: deltaPp,
      self_reported: d.self_reported_value ?? null, measured: d.measured_value ?? null });
  }
  return out.sort((a, b) => Math.abs(b.delta_pp) - Math.abs(a.delta_pp) || a.id.localeCompare(b.id));
}

// --- Failure streak / escalation -------------------------------------------
export function nextFailureStreak(current, statusOk) {
  const streak = Number.isSafeInteger(current) && current >= 0 ? current : 0;
  return statusOk ? 0 : streak + 1;
}

// --- The notification plan --------------------------------------------------
// One pure function computes everything the notifier may do. It returns the
// messages to send (`sends`), why others were held back (`skips`) and the state
// mutations. Mutations split into `baseline` (always applied, even without any
// send: first-run seeding, streak bookkeeping, escalation request record) and
// per-send `onSent` (applied ONLY after a Telegram send actually succeeded, so
// a missing credential can never fake a dedup entry).
// A failed run never advances the top5 baseline (it keeps `previous`) and a
// successful run clears any stale escalation request.
export function planNotifications({
  status_ok: statusOk, rc = null,
  top5: { previous: top5Previous = null, current: top5CurrentInput = [] } = {},
  datasets: { before: beforeDs = null, after: afterDs = null } = {},
  failure_streak: streakBefore = 0,
  failure_alert_last_sent_at: lastFailureAlertAt = null,
  notified = {},
  escalation_request: escalationRequest = null,
  summary_excerpt: summaryExcerpt = null,
  now = Date.now(),
} = {}) {
  const at = Number.isFinite(now) ? now : Date.parse(now);
  if (!Number.isFinite(at)) throw new Error('planNotifications: invalid now');
  const iso = new Date(at).toISOString();
  const current = sanitizeTop5(top5CurrentInput);
  const previous = top5Previous === null ? null : sanitizeTop5(top5Previous);
  const known = notified && typeof notified === 'object' ? notified : {};
  const sends = []; const skips = []; const baseline = {}; const seeded = previous === null;

  baseline.failure_streak = nextFailureStreak(streakBefore, statusOk);
  // A failed run keeps the last successful baseline; only a successful run
  // advances the watchlist snapshot.
  baseline.top5_state = statusOk ? current : previous;

  // Escalation request: state record (loud in the log), not a hidden bypass of
  // the weekly failure rate limit. The failure alert text mentions it.
  const escalationDue = !statusOk && baseline.failure_streak >= ESCALATION_THRESHOLD && !escalationRequest;
  if (escalationDue) baseline.escalation_request = { requested_at: iso, streak: baseline.failure_streak };
  // A successful run clears any stale escalation request.
  if (statusOk) baseline.escalation_request = null;

  // (b) failure, at most once per 7 days — the 7-day limit itself is only
  // advanced once a send is CONFIRMED (onSent below), never by planning.
  if (!statusOk) {
    const key = `failure:${iso.slice(0, 10)}`;
    const lines = [
      `⚠️ Benchmark Heaven Daily-Refresh fehlgeschlagen (rc=${rc ?? 'unbekannt'}).`,
      `Fehlerserie: ${baseline.failure_streak}. Nächste Warnung frühestens in 7 Tagen.`,
    ];
    if (escalationDue) lines.push(`ESKALATION ANGEFORDERT: ${baseline.failure_streak} aufeinanderfolgende Fehler — bitte manuell ops/daily/escalate.sh ausführen.`);
    if (typeof summaryExcerpt === 'string' && summaryExcerpt.trim()) lines.push('', summaryExcerpt.trim().slice(0, 1500));
    if (lastFailureAlertAt === null || at - lastFailureAlertAt >= FAILURE_ALERT_INTERVAL_MS) {
      sends.push({ kind: 'failure', key, text: lines.join('\n'), onSent: { failure_alert_sent_at: at } });
    } else skips.push({ kind: 'failure', key, reason: 'rate-limited' });
  }

  // Data events only from a successful run with both snapshots present.
  if (statusOk) {
    // (a) new family in the top 5 — but never on the very first run: seed only.
    if (seeded) skips.push({ kind: 'top5-entrant', key: null, reason: 'baseline-seeded' });
    else {
      const { entrants } = diffTop5Entrants(previous, current);
      if (entrants.length) {
        const key = `top5:${entrants.map((r) => r.family_key).sort().join('|')}`;
        if (known[key]) skips.push({ kind: 'top5-entrant', key, reason: 'duplicate' });
        else {
          const lines = [`🏆 Benchmark Heaven: Neu in den Top ${TOP_N} (Composite): ${entrants.map((r) => `${r.name} (${r.composite})`).join(', ')}`, ''];
          lines.push(...current.map((r, i) => `${i + 1}. ${r.name} — ${r.composite}`));
          lines.push('https://benchmarkheaven.com');
          sends.push({ kind: 'top5-entrant', key, text: lines.join('\n'), onSent: { notified_key: key } });
        }
      }
    }
    if (beforeDs && afterDs) {
      // (c1) meaningful new major model — one entry per new family (highest AA).
      const majors = findNewMajorModels(beforeDs, afterDs);
      if (majors.length) {
        const key = `major:${majors.map((m) => m.id).sort().join('|')}`;
        if (known[key]) skips.push({ kind: 'major-model', key, reason: 'duplicate' });
        else sends.push({ kind: 'major-model', key, onSent: { notified_key: key },
          text: [`🚀 Benchmark Heaven: bedeutende${majors.length > 1 ? ' neue Modelle' : 's neues Modell'} (AA ≥ ${NOTABLE_AA_INDEX}, neue Familie):`,
            ...majors.map((m) => `• ${m.name} — AA ${m.index}`), 'https://benchmarkheaven.com'].join('\n') });
      }
      // (c2) new exact-comparable self-reported-vs-measured divergence >= 10 pp
      const divergences = findNotableDivergences(beforeDs?.benchmark_results, afterDs?.benchmark_results);
      if (divergences.length) {
        const key = `divergence:${divergences.map((d) => d.id).sort().join('|')}`;
        if (known[key]) skips.push({ kind: 'divergence', key, reason: 'duplicate' });
        else sends.push({ kind: 'divergence', key, onSent: { notified_key: key },
          text: [`📊 Benchmark Heaven: neue exakt vergleichbare Abweichung Selbstauskunft vs. Messung (≥ ${DIVERGENCE_ALERT_PP} Prozentpunkte):`,
            ...divergences.map((d) => `• ${d.model_id} / ${d.benchmark_id}: ${d.self_reported} vs. ${d.measured} ${d.unit} (Δ ${d.delta_pp > 0 ? '+' : ''}${Math.round(d.delta_pp * 10) / 10} pp)`),
            'https://benchmarkheaven.com/benchmarks'].join('\n') });
      }
    }
  }
  return { sends, skips, baseline, seeded, evaluated_at: iso };
}

// --- Cheap worker selection (producer + different-family critic) ------------
// Input: parsed output of `node ops/rebuild-2026-09/bin/pick-worker-models.mjs --json`
// (which already enforces the AA >= 34 gate against our own dataset). We
// defensively re-check the gate and additionally cap cost at <= $4 per million
// prompt AND completion tokens. The critic must come from a different vendor
// family than the producer. Astra (Codex) is never a daily worker.
export function selectProducerCritic(catalog, { maxUsdPerMtok = MAX_WORKER_USD_PER_MTOK, minAa = MIN_WORKER_AA_INDEX } = {}) {
  if (!Number.isFinite(minAa) || minAa < 34 || !Number.isFinite(maxUsdPerMtok) || maxUsdPerMtok <= 0 || maxUsdPerMtok > MAX_WORKER_USD_PER_MTOK) throw new Error('Invalid daily worker qualification/cost limits');
  if (!catalog || typeof catalog !== 'object') throw new Error('worker catalog missing');
  const pool = [...(catalog.free_verified ?? []), ...(catalog.cheap_verified ?? [])];
  const viable = pool.filter((m) => m && typeof m.id === 'string'
    && Number.isFinite(m.aa_intelligence_index) && m.aa_intelligence_index >= minAa
    && Number.isFinite(m.input_per_1m) && Number.isFinite(m.output_per_1m)
    && m.input_per_1m >= 0 && m.output_per_1m >= 0
    && m.input_per_1m <= maxUsdPerMtok && m.output_per_1m <= maxUsdPerMtok
    && typeof m.family === 'string' && m.family)
    .sort((a, b) => (a.input_per_1m + a.output_per_1m) - (b.input_per_1m + b.output_per_1m));
  if (!viable.length) throw new Error(`no viable daily worker (AA >= ${minAa}, <= $${maxUsdPerMtok}/Mtok prompt+completion)`);
  const producer = viable[0];
  const critic = viable.find((m) => m.family !== producer.family);
  if (!critic) throw new Error(`no different-family critic available (producer family: ${producer.family})`);
  return { producer, critic };
}

// --- Staging / commit scope / publication -----------------------------------
// Parse `git status --porcelain=v1` output. Handles modified/added/deleted/
// untracked and `R  old -> new` renames, including C-quoted paths. Returned
// paths are repo-relative, unquoted.
export function parseStatusPorcelain(text) {
  const rows = [];
  for (const line of String(text ?? '').split('\n')) {
    if (!line.trim()) continue;
    const code = line.slice(0, 2);
    let path = line.slice(3);
    if (code.includes('R') || code.includes('C')) {
      const arrow = path.lastIndexOf(' -> ');
      if (arrow >= 0) path = path.slice(arrow + 4);
    }
    rows.push({ code, path: unquoteGitPath(path) });
  }
  return rows;
}

function unquoteGitPath(path) {
  const trimmed = path.trim();
  if (!trimmed.startsWith('"')) return trimmed;
  try { return JSON.parse(trimmed); } catch { return trimmed.slice(1, -1); }
}

// Which paths may a daily staging commit contain? Data, plus explicitly
// declared new source evidence (reported by refreshBenchmarks). Anything else
// blocks publication — a daily run must never smuggle ops or app changes.
export function assessCommitScope(changedPaths, extraAllowed = []) {
  const prefixes = [...ALLOWED_COMMIT_PREFIXES];
  const extras = new Set(extraAllowed.filter((p) => typeof p === 'string' && p && !p.startsWith('/') && !p.includes('..')));
  const allowed = []; const rejected = [];
  for (const raw of changedPaths) {
    const path = String(raw ?? '');
    if (!path || path.startsWith('/') || path.split('/').includes('..')) { rejected.push(path); continue; }
    if (prefixes.some((p) => path.startsWith(p)) || extras.has(path)) allowed.push(path);
    else rejected.push(path);
  }
  return { ok: rejected.length === 0, hasChanges: changedPaths.length > 0, allowed, rejected };
}

// Publication decision. Rollback semantics: anything other than `publish`
// leaves main untouched; the staged workdir is simply retained for inspection.
export function planPublication({ dryRun = false, checksOk = false, scope } = {}) {
  if (!checksOk) return { action: 'abort', reason: 'one or more collection/review/check steps failed; main stays untouched' };
  if (!scope?.ok) return { action: 'abort', reason: `commit scope rejected (outside data/evidence): ${(scope?.rejected ?? []).join(', ') || 'unknown'}` };
  if (!scope.hasChanges) return { action: 'skip', reason: 'no data changes; nothing to commit' };
  if (dryRun) return { action: 'dry-run', reason: '--dry-run: commit/push/suppress active but withheld' };
  return { action: 'publish', reason: 'staged run green; ff-only publication allowed' };
}

// Final process exit code from the recorded step outcomes.
export function planExitCode(steps) {
  return (steps ?? []).some((s) => s.required !== false && !s.ok) ? 1 : 0;
}

